mapper.select:
SELECT * FROM ( SELECT PL.WAREHOUSING_NO , PL.ORDER_NO , V.VENDOR_CODE , V.VENDOR_NAME , IM.ITEM_CODE , IM.ITEM_NAME , PL.WAREHOUSING_DATE , PL.WAREHOUSING_AMOUNT , PL.WAREHOUSING_QTY , PL.UNIT_PRICE , PL.WAREHOUSING_TYPE , GET_CODE_NAME(PL.WAREHOUSING_TYPE, 'WT', PL.COMPANY_CODE, #{default_language}) AS WAREHOUSING_TYPE_NAME , COALESCE(COO_CERTIFY_YN, 'N') AS COO_CERTIFY_YN , DV.DIVISION_NAME , DV.DIVISION_CODE , V.MAIL_SEND_YN FROM PO_LEDGER PL INNER JOIN DIVISION DV ON PL.DIVISION_CODE = DV.DIVISION_CODE AND PL.COMPANY_CODE = DV.COMPANY_CODE AND DV.STATUS = 'Y' INNER JOIN VENDOR V ON V.VENDOR_CODE = PL.VENDOR_CODE AND V.COMPANY_CODE = PL.COMPANY_CODE INNER JOIN ITEM_MST IM ON IM.ITEM_CODE = PL.ITEM_CODE AND IM.COMPANY_CODE = PL.COMPANY_CODE LEFT JOIN LATERAL ( SELECT 'Y' AS COO_CERTIFY_YN FROM EXT_COO_CERTIFY_MST ECM WHERE ECM.COO_CERTIFY_NO = PL.COO_CERTIFY_NO AND ECM.VENDOR_CODE = PL.VENDOR_CODE AND ECM.DIVISION_CODE = PL.DIVISION_CODE AND ECM.COMPANY_CODE = PL.COMPANY_CODE LIMIT 1 ) ON 1=1 WHERE PL.COMPANY_CODE = #{company_code} ) WHERE 1=1
AND WAREHOUSING_DATE BETWEEN #{from_date} AND #{to_date}
AND (ITEM_CODE ILIKE '%' || #{item} || '%' OR ITEM_NAME ILIKE '%' || #{item} || '%' )
AND COO_CERTIFY_YN = #{coo_certify_yn}
AND DIVISION_CODE = #{division_code}
AND WAREHOUSING_TYPE = #{warehousing_type}
AND MAIL_SEND_YN = #{mail_send_yn}
